// Community Awareness lessons 1–5: the event and choosing a topic, researching the issue, planning goals and timelines,
// building community partnerships, and designing campaign activities and original items.
const RULES=['HOSA Community Awareness 2026–27 guidelines and rating sheets','https://hosa.org/wp-content/uploads/2026/08/Community-Awareness-26-27.pdf'];
const CHR=['County Health Rankings & Roadmaps','https://www.countyhealthrankings.org/'];
const PLACES=['CDC PLACES: local data for better health','https://www.cdc.gov/places/index.html'];
const HP_SDOH=['Healthy People 2030: social determinants of health','https://odphp.health.gov/healthypeople/priority-areas/social-determinants-health'];
const CTB=['University of Kansas Community Tool Box','https://ctb.ku.edu/en'];
const CDC_COMM=['CDC: health communication','https://www.cdc.gov/health-communication/php/index.html'];
const CDC_YRBS=['CDC: Youth Risk Behavior Surveillance System','https://www.cdc.gov/yrbs/index.html'];
const WHO_HEALTH=['WHO: constitution and definition of health','https://www.who.int/about/governance/constitution'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
const sort=(title,buckets,items)=>({t:'w',kind:'sort',title,buckets,items});
const flip=(title,cards)=>({t:'w',kind:'flip',title,cards});
const kase=(title,nodes)=>({t:'w',kind:'case',title,start:'a',nodes});
const chk=(q,options,why)=>({t:'check',q,options,why});
const ex=(title,prompt,steps,answer)=>({t:'example',title,prompt,steps,answer});

export const CA1={title:'The event and choosing a campaign topic',hook:'A team notices that many classmates skip breakfast and fall asleep in first period. Another sees litter clogging a creek behind the school. A third learns that few teens know they can register as organ donors. Each spots a local health issue and decides to do something about it. Community Awareness turns that instinct into a year-long campaign—and rewards teams that make a measurable difference.',objectives:['Describe the Community Awareness event, its rounds and scoring.','Explain the four health domains for campaign topics.','Choose a focused topic that fits your community’s needs.','Plan a year-long campaign timeline.'],sections:[
['The event at a glance',[
'Community Awareness is a **team event for 2–6 members**. Teams plan and carry out a **local community awareness campaign** on one health or safety issue of local, state or national interest, then document it in a **portfolio**. All campaign activities must happen between **July 1, 2026 and May 15, 2027**.',
'**Round One** is a pre-judged **portfolio** of up to **12 pages** (not counting references), uploaded by **one team member** as **one PDF** by **May 15**; it is worth **80 points**. Every team that uploads on time receives a **Round Two** appointment: a **five-minute presentation** to judges. Notecards are allowed (electronic notes may not be shown), but **no other materials or visual aids**. **All team members must take an active role**.',
'Final scores combine the portfolio and presentation. Ties are broken by the rating-sheet sections with the highest point values.',
{t:'table',caption:'Event structure',head:['Round','What you do','Notes'],rows:[['One','Portfolio (≤12 pages + references)','Pre-judged, 80 points, one PDF by May 15'],['Two','5-minute presentation','Notecards only; every member participates'],['Timeline','Campaign activities','July 1, 2026 – May 15, 2027']]}]],
['The four health domains',[
'Topics come from four domains. **Physical health**—the normal functioning of the body—such as public sanitation, diabetes, assistive technology, brain health or reducing environmental risks for children. **Mental health**—psychological and emotional well-being—such as addictive behavior, depression and anxiety, eating disorders and body image or insomnia.',
'**Environmental health**—factors in the environment that affect health—such as clean energy, light or air pollution, sustainability or water pollution. **Societal health**—non-medical factors that affect health outcomes—such as poverty and hunger, education gaps, public health infrastructure, work–life balance, climate change, deforestation, adolescent health and ageism or digital health.',
'These domains reflect the idea that health is more than the absence of disease. The World Health Organization defines health as complete physical, mental and social well-being, and the social determinants of health show how where people live, learn and work shapes their health.',
sort('Health domain',['Physical','Mental','Environmental','Societal'],[['Diabetes prevention',0],['Teen depression and anxiety',1],['Air pollution near schools',2],['Food insecurity',3],['Brain health and concussion',0],['Digital health and screen time',3]])]],
['Choosing a focused topic',[
'The best topics are **specific**, **local** and **actionable**. “Mental health” is too broad; “helping ninth graders recognize anxiety and find support at school” is focused. “Pollution” is too broad; “reducing litter and runoff in Mill Creek” is focused. A focused topic lets you set clear goals, find the right partners and measure impact.',
'Ask: Is this a real problem in **our** community? Can we find **evidence** of it? Is there an **action** people can take? Can we **reach** the people affected? Do **partners** exist who can help? Does our team care about it enough to work on it all year?',
'Original campaigns are encouraged, but partnering with **established campaigns** (such as organ donor registration drives or national awareness months) is acceptable—just make your local contribution clear.',
sort('Focused enough?',['Focused and actionable','Too broad'],[['Increase teen organ donor registration at our school',0],['Fix all health problems',1],['Reduce vaping among middle schoolers in our district',0],['The environment',1],['Teach families in our neighborhood about safe medication disposal',0],['Mental health in general',1]])]],
['What judges look for',[
'Judges want a campaign that **clearly focuses** on a health or safety issue, uses **in-depth research**, involves **community partners**, includes **original, high-quality activities and items**, earns **publicity in several forms of media**, shows **every team member participating** and documents **real impact** with dated evidence and realistic audience estimates.',
'The rating sheet repeatedly rewards **four or more**: four or more forms of media, four or more forms of evidence of community participation, four or more original items and four or more examples of partnership impact. Plan for these numbers from the start.',
'The campaign should also promote **goodwill** for HOSA and your health science program—your work represents your chapter in the community.',
flip('“Four or more” targets',[['Publicity','Four or more forms of media'],['Impact evidence','Four or more dated forms of evidence'],['Original items','Four or more high-quality items'],['Partnerships','Four or more examples of partner impact'],['Participation','Evidence of every team member'],['Audience','Realistic estimates with evidence']])]],
['A year-long timeline',[
'Plan backward from **May 15**. **July–August:** form the team, brainstorm topics and research needs. **September:** choose the topic, set goals and contact partners. **October–February:** run activities, create original items and seek publicity. **March–April:** final activities, measure impact and collect evidence. **Late April–early May:** assemble and proofread the portfolio, upload early and rehearse the presentation.',
'Use a **shared calendar** with deadlines and owners. Document **as you go**: photos, dated programs, screenshots of posts with view counts and partner emails. Waiting until spring to gather evidence often means missing dates or numbers.',
'Build in time for **reflection** after each activity so you can improve the next one and later describe areas for improvement.',
order('Campaign timeline',['Form the team and research needs','Choose the topic and set goals','Contact partners','Run activities and create items','Seek publicity and track audiences','Measure impact and collect evidence','Build the portfolio and upload by May 15'])]],
['Roles within the team',[
'Divide responsibilities so the work is shared and everyone has evidence of participation. Possible roles: **campaign lead** (coordinates the calendar), **research lead** (gathers data and sources), **partnership lead** (communicates with partners), **media lead** (publicity and social media), **design lead** (original items) and **documentation lead** (photos, dates, audience numbers and portfolio).',
'Every member should participate in campaign events, not only behind the scenes, because judges score **evidence of all team members’ quality participation**. Rotate presenting duties at events so each member appears in dated photos or programs.',
'Hold short weekly check-ins to review progress, solve problems and update the calendar.',
match('Role and responsibility',[['Campaign lead','Coordinates the calendar and team'],['Research lead','Gathers data and sources'],['Partnership lead','Communicates with partners'],['Media lead','Publicity and social media'],['Design lead','Creates original items'],['Documentation lead','Photos, dates and audience numbers']])]],
['Practice scenario',[
kase('Picking a topic',{a:{text:'Your team of four is torn between “health” and “reducing sugary drink consumption among students at our school.” (Scenario invented for practice.) Which is better?',choices:[['The sugary drink topic—focused, local and actionable','b','Correct.',true],['“Health”—it covers everything','b','Too broad to plan or measure.',false]]},b:{text:'Which domain does it fit?',choices:[['Physical health','c','Correct. It affects the body’s normal functioning.',true],['Environmental health','c','It mainly concerns nutrition and the body.',false]]},c:{text:'You plan a timeline backward from May 15 and assign roles so every member participates.',end:true}})]]
],takeaways:['Teams of 2–6 run a local campaign between July 1, 2026 and May 15, 2027; Round One is a pre-judged portfolio (≤12 pages plus references, 80 points, one PDF by May 15); Round Two is a 5-minute presentation with notecards only and every member participating.','Topics come from physical, mental, environmental or societal health; choose a specific, local, actionable topic with evidence, partners and a clear action.','Plan for “four or more” (media, impact evidence, original items, partner examples), evidence of every member’s participation and a timeline built backward from May 15 with documentation as you go.'],terms:[['Community awareness campaign','An organized effort to educate a community about a health issue and inspire action.'],['Societal health','Non-medical factors such as poverty and education that affect health outcomes.'],['Target audience','The specific group a campaign is designed to reach.']],mcqs:[q('How many members may be on a Community Awareness team?','2–6','1','7–10','Exactly 3','Team event.'),q('When must campaign activities take place?','July 1, 2026 – May 15, 2027','January–December 2026','Any time','Only in summer','Competition year.'),q('What is the maximum portfolio length?','12 pages, not counting references','20 pages','6 pages','No limit','Pre-judged.'),q('How long is the Round Two presentation?','5 minutes','10 minutes','2 minutes','15 minutes','Notecards only.'),q('Which topic is in the environmental health domain?','Air pollution near schools','Diabetes','Depression','Poverty','Environment.'),q('Which topic is in the societal health domain?','Food insecurity','Insomnia','Water pollution','Brain health','Non-medical factors.'),q('Which topic is focused and actionable?','Increase teen organ donor registration at our school','Health in general','The environment','Everything about wellness','Specific and local.'),q('How many forms of media earn the top publicity score?','Four or more','One','Two','Three','Plan for four.')],frq:{prompt:'Explain how your team would choose a Community Awareness topic and plan a year-long campaign that meets the event requirements.',rubric:[['Domains',['physical','mental','environmental','societal','domain']],['Focus',['specific','local','actionable','evidence','partners','action']],['Timeline',['july 1','may 15','calendar','backward','document']],['Judging targets',['four or more','media','evidence','original items','participation','roles']]],model:'Our team would start in July by brainstorming issues we see in our community and sorting them into the four domains: physical, mental, environmental and societal health. We would then research which issues have local evidence, an action people can take, partners who could help and a group we can reach. For example, if our school nurse reported that many students drink several sugary drinks a day and our county data showed rising rates of teen obesity, we might choose “reducing sugary drink consumption among students at our high school,” a focused physical health topic. We would plan backward from May 15: choose the topic and set goals in September, contact partners such as the school nutrition department and a local hospital dietitian, run activities and create original items from October to February, seek publicity throughout and spend March and April measuring impact before building the portfolio. We would assign roles—campaign, research, partnership, media, design and documentation leads—while making sure every member participates in events so the portfolio shows evidence of all members. From the start, we would aim for the rating sheet’s “four or more” targets: four forms of media, four forms of dated impact evidence, four original items and four examples of partner impact, documenting photos, dates and audience numbers as we go rather than waiting until spring.'},sources:[RULES,HP_SDOH,WHO_HEALTH]};

export const CA2={title:'Researching the health issue',hook:'Judges score research that is “in-depth and beyond the obvious.” A campaign about vaping that only says “vaping is bad” earns little; one that explains how many students in your county vape, why flavored products appeal to teens and which prevention strategies work earns much more. Good research also tells you what message will actually change behavior.',objectives:['Find local, state and national data on a health issue.','Evaluate sources for credibility and relevance.','Conduct an ethical local needs assessment.','Use research to shape campaign messages and goals.'],sections:[
['Why research matters',[
'Research does three jobs. It **proves the problem exists** in your community, it helps you **understand causes** and **solutions**, and it **guides your message** so the campaign is accurate and effective. Judges score research in Round Two (understanding of the problem) and look for it in the activities and items in your portfolio.',
'Good research also prevents mistakes. A campaign that spreads inaccurate health information can harm people and damage HOSA’s reputation. Every fact on a flyer or social media post should be traceable to a credible source in your reference list.',
'Plan research early, before choosing activities, and keep updating it as you learn from your partners and community.',
chk('Which is NOT a main job of campaign research?',['Making the portfolio longer','Proving the problem exists locally','Understanding causes and solutions','Guiding an accurate message'],'Research serves the campaign, not page count.')]],
['Local and national data sources',[
'Start with **local and state data**. **County Health Rankings & Roadmaps** compares counties on health outcomes and factors such as smoking, obesity, access to care and income. **CDC PLACES** provides local estimates for chronic disease measures by county, city and even census tract. **State and local health departments** publish reports on topics like overdose, vaccination and injuries.',
'For youth topics, use your state’s **Youth Risk Behavior Survey** results and school climate surveys. For national context, use CDC, NIH, MedlinePlus and Healthy People 2030 objectives. Environmental topics can draw on the EPA and local water or air quality reports.',
'Record each source’s **title, organization, date and URL** as you go, so building the reference page is easy.',
match('Source and what it provides',[['County Health Rankings','County comparisons of health outcomes and factors'],['CDC PLACES','Local chronic disease estimates'],['State health department','State reports on specific issues'],['YRBS','Youth health behaviors'],['Healthy People 2030','National health objectives'],['EPA air or water reports','Environmental data']])]],
['Evaluating sources',[
'Use credible sources: government agencies (.gov), universities (.edu), professional health organizations and peer-reviewed journals. Check **who** wrote it, **when**, **why** (to inform or to sell?) and **what evidence** supports it. Avoid relying on social media posts, commercial sites selling products or outdated information.',
'Apply the same fact-checking habits taught in public health: read laterally to see what others say about an unfamiliar site, trace statistics to their original source and prefer recent data. Note the **population** a statistic describes—national data may not match your community.',
'When local data are limited, say so honestly and combine national data with your own local needs assessment.',
sort('Credible source for a campaign?',['Credible','Not credible'],[['A state health department report',0],['An influencer selling detox tea',1],['A peer-reviewed journal article',0],['An undated anonymous blog',1],['CDC fact sheet',0],['A forwarded message with no source',1]])]],
['Conducting a local needs assessment',[
'A **needs assessment** finds out what your specific community knows, believes and needs. Methods include short **anonymous surveys** (with school or partner approval), **interviews** with experts such as school nurses, counselors or public health workers, **focus groups** and **observation** (for example, counting litter at a park).',
'Follow ethical rules: get permission, keep surveys anonymous, avoid sensitive personal questions and never collect identifying information you do not need. Ask about **knowledge**, **attitudes** and **barriers**: “Do you know how to safely dispose of old medications?” “What stops you from drinking more water at school?”',
'Needs assessment results give you a **baseline** for measuring impact later and strong material for explaining your campaign’s purpose.',
order('Running a needs assessment',['Define what you need to learn','Get permission from the school or partner','Write short, anonymous questions','Collect responses or interviews','Summarize results','Use findings to set goals and messages'])]],
['Understanding causes and solutions',[
'Research should go **beyond the obvious** by explaining **why** the problem exists. Use the **social-ecological model**: individual factors (knowledge, habits), relationships (peers, family), community (schools, businesses, neighborhoods) and policy (laws, rules). For example, sugary drink consumption is shaped by taste preferences, peer habits, vending machine choices and marketing.',
'Then find **evidence-based solutions**: What has worked elsewhere? Resources like the **Community Tool Box** and CDC program guides describe strategies such as education combined with environmental changes (for example, water bottle filling stations). Campaigns are stronger when they pair awareness with an easy action.',
'Explaining causes and solutions shows judges a “deep, insightful understanding,” the highest research rating.',
sort('Level of influence (sugary drinks example)',['Individual','Relationship','Community','Policy'],[['Liking the taste of soda',0],['Friends buying soda together',1],['Vending machines full of sugary drinks',2],['School wellness policy limiting sugary drinks',3],['Not knowing how much sugar a drink contains',0],['Corner store pricing',2]])]],
['From research to message',[
'Turn research into a **clear message** and a **call to action**. A message should be accurate, simple, relevant to the target audience and positive: “Swap one soda a day for water—your body and brain will thank you.” Include a credible fact to build trust and an easy action to take.',
'Tailor messages to your audience. Teens may respond to social norms (“Most students at our school drink water at lunch”), while parents may respond to health and cost. Test draft messages with a few people from the audience before launching.',
'Keep a **message map**: one core message, three supporting facts with sources and a call to action. Use it consistently across all activities and items.',
ex('Building a message map','Create a message map for an invented sugary drink campaign.',['Core message: Choose water to feel and focus better.','Fact 1: A 20-oz soda can contain about 16 teaspoons of sugar (cite a nutrition source).','Fact 2: Mild dehydration can affect focus and mood (cite a health source).','Fact 3: Our school survey found most students want more water stations (invented for practice).','Call to action: Fill a reusable bottle at the new water station today.'],'One clear message, three sourced facts and a simple action (survey result invented for practice).')]],
['Practice scenario',[
kase('Research gap',{a:{text:'Your team found national vaping data but no data for your county. (Scenario invented for practice.) What should you do?',choices:[['Check state YRBS and health department reports, then run an approved anonymous school survey','b','Correct.',true],['Invent a local statistic','b','Never invent data.',false]]},b:{text:'Your survey finds many students do not know vaping can harm the developing brain. How does this shape your campaign?',choices:[['Make brain health a core message with a simple action, such as where to get help quitting','c','Correct.',true],['Ignore it','c','Use findings to guide messages.',false]]},c:{text:'Your survey also becomes the baseline for measuring impact in the spring.',end:true}})]]
],takeaways:['Research proves the problem exists locally, explains causes and solutions and guides accurate messages; every fact should trace to a credible source.','Use County Health Rankings, CDC PLACES, state and local health departments, YRBS, Healthy People 2030 and environmental reports; evaluate sources by author, date, purpose and evidence; record citations as you go.','Run an ethical, approved, anonymous needs assessment for a baseline; use the social-ecological model to explain causes; choose evidence-based solutions; build a message map with one core message, three sourced facts and a call to action.'],terms:[['Needs assessment','A process to learn what a community knows, believes and needs.'],['Baseline','A starting measurement used to show change later.'],['Message map','A core message supported by facts and a call to action.']],mcqs:[q('Which source compares counties on health outcomes and factors?','County Health Rankings & Roadmaps','A celebrity blog','A product website','A forwarded text','Local data.'),q('CDC PLACES provides:','Local estimates for chronic disease measures','Only national averages','Product reviews','Hospital menus','Small-area data.'),q('Which is a credible source?','A state health department report','An undated anonymous blog','An influencer selling products','A rumor','Evaluate sources.'),q('What should a needs assessment survey be?','Approved, short and anonymous','Long and identifying','Optional to approve','About private trauma','Ethics.'),q('A baseline is used to:','Show change later','Replace research','Pick team colors','Write the title page','Measure impact.'),q('In the social-ecological model, a school wellness policy is at the:','Policy level','Individual level','Relationship level','Genetic level','Rules and laws.'),q('What does a message map include?','A core message, supporting facts and a call to action','Only photos','A budget','A list of team members','Consistency.'),q('What should you do if local data are missing?','Use state data and conduct a local needs assessment','Invent numbers','Skip research','Copy another school’s data','Honesty.')],frq:{prompt:'Describe how your team would research a local health issue, including data sources, a needs assessment and how research would shape your message.',rubric:[['Sources',['county health rankings','places','health department','yrbs','healthy people','credible']],['Evaluation',['author','date','purpose','evidence','lateral','record']],['Needs assessment',['survey','anonymous','permission','interview','baseline','knowledge','barriers']],['Message',['causes','solutions','social-ecological','message map','call to action','audience']]],model:'For a campaign on safe medication disposal, we would begin with credible data: our state health department’s overdose and poisoning reports, County Health Rankings for our county’s drug overdose deaths and national guidance from the FDA and DEA on disposal and take-back programs. We would evaluate each source by its author, date, purpose and evidence, read laterally about unfamiliar sites and record the title, organization, date and URL for our reference page. Because local behavior data were limited, we would run a needs assessment approved by our school and a community pharmacy partner: a short, anonymous survey asking families whether they keep unused medications, know where take-back sites are and what stops them from disposing of medicines safely, plus interviews with a pharmacist and the school nurse. The results would become our baseline. Using the social-ecological model, we would explain causes at several levels—individuals not knowing about take-back sites, family habits of saving medications, few convenient disposal locations and policies on take-back days. Research on what works would point us to pairing education with convenient disposal options. We would build a message map with a core message—“Clean out your cabinet, protect your family”—three sourced facts and a clear call to action, such as dropping unused medicines at the pharmacy kiosk, and tailor the wording for parents and grandparents.'},sources:[RULES,CHR,PLACES,CDC_YRBS]};

export const CA3={title:'Setting goals, objectives and the campaign plan',hook:'The official guidelines give an example goal: encourage 10% of high school students to sign up as organ and tissue donors between September 1 and May 10, using an original PSA on social media, a booth at a February health fair and monthly reminders in the school newspaper. That one sentence shows judges exactly what success looks like. This lesson helps your team write goals and plans that clear.',objectives:['Write a campaign goal and SMART objectives.','Define a target audience and tailor the campaign to it.','Choose activities that match objectives.','Build a logic model linking activities to outcomes.'],sections:[
['Goals and SMART objectives',[
'A **goal** states the overall change you want; **objectives** are specific, measurable steps toward it. Use **SMART** objectives: **S**pecific, **M**easurable, **A**chievable, **R**elevant and **T**ime-bound. The guidelines’ example: “Encourage **10%** of our high school students to sign up to be organ and tissue donors **between September 1 and May 10**.”',
'Write objectives for **awareness** (how many people you will reach), **knowledge** (what they will learn), **behavior** (what they will do) and **partnerships** (who you will work with). For example: “By March 1, 300 students will view our PSA,” “80% of workshop participants will name two signs of a stroke,” “50 families will drop off unused medications at take-back day.”',
'Clear objectives earn points in Round Two, where judges score whether activities had **clear objectives** and **accomplishments**, and they guide what evidence you collect.',
order('Writing a SMART objective',['Name the audience','State the specific change','Add a number','Check it is achievable','Connect it to the health issue','Set a date range'])]],
['Defining the target audience',[
'A **target audience** is the specific group you want to reach—students at your school, parents of young children, older adults at a senior center, local athletes, or a neighborhood near a polluted creek. Your title page must name the target audience.',
'Learn about your audience: their age, language, where they get information, what they care about and what barriers they face. A campaign for teens might use short videos and peer messengers; one for older adults might use large-print flyers and talks at senior centers; one for Spanish-speaking families needs bilingual materials.',
'You can have a **primary** audience (the people whose behavior you want to change) and **secondary** audiences (people who influence them, such as parents or teachers).',
match('Audience and best channel',[['High school students','Short videos and peer-led events'],['Parents of young children','School newsletters and pediatric clinics'],['Older adults','Senior center talks and large-print flyers'],['Spanish-speaking families','Bilingual materials and trusted community leaders'],['Athletes','Coaches and team meetings'],['Local businesses','Chamber of commerce meetings']])]],
['Choosing activities that fit objectives',[
'Every activity should serve at least one objective. To raise **awareness**, use broad-reach activities such as social media campaigns, morning announcements, posters and newspaper articles. To build **knowledge and skills**, use workshops, demonstrations and health fairs. To change **behavior**, make the action easy: sign-up tables, take-back events, water bottle refill stations or pledge drives.',
'Mix activities so your campaign reaches people several times in different ways—repetition builds awareness and behavior change. The rating sheet rewards **exceptional, original activities** shown across a **timeline** that highlight research and a **call to action**.',
'Ask of each idea: Which objective does it serve? How will we measure it? Who are our partners? What evidence will we collect?',
sort('Main purpose of the activity',['Raise awareness','Build knowledge or skills','Make action easy'],[['Social media PSA',0],['Hands-only CPR workshop',1],['Organ donor sign-up table',2],['School newspaper article',0],['Healthy snack demonstration',1],['Medication take-back event',2]])]],
['The logic model',[
'A **logic model** shows how your campaign is supposed to work: **inputs** (team time, partners, materials) → **activities** (events, posts, workshops) → **outputs** (people reached, items distributed) → **outcomes** (knowledge, attitudes and behaviors that change) → **impact** (long-term health improvement).',
'Logic models help you check that activities connect to outcomes and show judges a thoughtful plan. They also tell you what to measure: outputs are counted (attendance, views), while outcomes need surveys, sign-up counts or observation.',
'Include a simple version of your logic model in planning notes, and describe its key links in your presentation when explaining goals and accomplishments.',
order('Logic model',['Inputs: time, partners, materials','Activities: events, posts, workshops','Outputs: people reached, items distributed','Outcomes: knowledge and behavior change','Impact: long-term health improvement'])]],
['Budget, resources and feasibility',[
'Most campaigns run on small budgets. List the **resources** you need—printing, supplies, event space, transportation—and find free or low-cost options: school printing, partner donations, free design tools and social media. Ask partners whether they can provide materials, such as a hospital donating educational handouts.',
'Check **feasibility**: Can your team realistically complete each activity with its time and resources? Overcommitting leads to rushed, lower-quality work. Judges value quality over the number of activities.',
'Follow school and partner rules for fundraising, events and communication. Keep receipts and records if you spend money.',
chk('Which plan is most feasible for a team of three with a small budget?',['Three well-planned activities with partner support and free digital tools','Twenty events in one month','A paid television ad campaign','A citywide festival with no partners'],'Quality and feasibility matter more than size.')]],
['Writing the campaign plan',[
'Put it together in a one-page **campaign plan**: title, target audience, health issue and research summary, goal, objectives, activities with dates and owners, partners, publicity plan, evidence to collect and budget. Share it with partners and your advisor.',
'Refer back to the plan often and update it as the campaign evolves. If an activity does not work, note why and adjust—this becomes part of your **areas for improvement**, which the presentation must include.',
'A clear plan also makes your Round Two explanation of purpose, goals and activities concise and confident.',
ex('A campaign goal statement','Write a goal statement in the style of the guidelines’ example (invented details).',['Audience: students at our high school','Change: 25% sign a “Rethink Your Drink” pledge','Time: between October 1 and April 30','Activities: original social media series, a February health fair booth and a water bottle challenge with the nutrition department','Measurement: pledge sign-ups and water station counter readings'],'“Our goal is for 25% of students at our high school to sign the Rethink Your Drink pledge between October 1 and April 30, through an original social media series, a February health fair booth and a water bottle challenge with our school nutrition department” (invented for practice).')]],
['Practice scenario',[
kase('Fixing a vague goal',{a:{text:'A draft goal says, “We want people to be healthier.” (Scenario invented for practice.) What is missing?',choices:[['Audience, a measurable change, activities and a time frame','b','Correct.',true],['Nothing; it is perfect','b','It is too vague to measure.',false]]},b:{text:'Which revision is best?',choices:[['“Increase the number of seniors at Oak Senior Center who can name three stroke signs from 20% to 70% between November and March through monthly workshops”','c','Correct. SMART.',true],['“Teach everyone everything about strokes”','c','Not specific or measurable.',false]]},c:{text:'You add the goal to your campaign plan and decide how to measure it with short pre- and post-quizzes.',end:true}})]]
],takeaways:['Write a goal and SMART objectives (specific, measurable, achievable, relevant, time-bound) for awareness, knowledge, behavior and partnerships, like the guidelines’ 10% organ donor example.','Define primary and secondary target audiences and tailor channels; choose activities that each serve an objective—broad-reach for awareness, workshops for skills and easy actions for behavior.','Use a logic model (inputs, activities, outputs, outcomes, impact), plan for feasibility and low cost and write a one-page campaign plan you update throughout.'],terms:[['SMART objective','A specific, measurable, achievable, relevant and time-bound target.'],['Logic model','A diagram linking inputs and activities to outputs, outcomes and impact.'],['Call to action','A specific step the audience is asked to take.']],mcqs:[q('What does the T in SMART stand for?','Time-bound','Targeted','Tested','Total','Deadline.'),q('Which is a SMART objective?','Increase pledge sign-ups to 25% of students between October and April','Make people healthier','Do a lot of events','Be famous','Specific and timed.'),q('In the guidelines’ example, what percentage of students was the organ donor goal?','10%','50%','100%','1%','Example goal.'),q('Which activity mainly makes action easy?','A medication take-back event','A newspaper article','A poster','A podcast','Behavior.'),q('In a logic model, attendance counts are:','Outputs','Inputs','Impact','Goals','Counted results.'),q('Knowledge and behavior changes are:','Outcomes','Inputs','Activities','Resources','Results of activities.'),q('What must the title page name?','The target audience','The budget','The judges','Each member’s GPA','Required item.'),q('Why check feasibility?','Overcommitting leads to lower-quality work','It is not needed','To add more events','To avoid partners','Quality over quantity.')],frq:{prompt:'Write a goal, three SMART objectives and a brief logic model for an invented Community Awareness campaign.',rubric:[['Goal',['goal','audience','change','time','activities']],['SMART objectives',['specific','measurable','number','date','awareness','knowledge','behavior']],['Logic model',['inputs','activities','outputs','outcomes','impact']],['Feasibility',['partners','resources','measure','evidence','plan']]],model:'Our invented campaign addresses stroke awareness among older adults. Goal: Between November 1 and March 31, increase the percentage of members at Oak Senior Center who can name three warning signs of stroke and know to call 911 from 20% to 70%, through monthly workshops, large-print bilingual flyers and a local radio interview, in partnership with the center and a hospital stroke coordinator. Objective 1 (awareness): By March 31, reach at least 400 older adults through flyers distributed at the center, two pharmacies and a radio segment. Objective 2 (knowledge): By March 31, at least 70% of workshop participants will correctly name three stroke warning signs on a short post-workshop quiz, up from a 20% baseline. Objective 3 (behavior): By March 31, at least 50 participants will post a magnet with stroke signs and the 911 reminder on their refrigerators and report doing so in a follow-up call. Logic model: inputs include our five team members, the senior center, the hospital stroke coordinator, donated magnets and free design tools; activities include four workshops, flyer distribution and a radio interview; outputs include the number of attendees, flyers distributed and radio audience; outcomes include improved knowledge and the action of posting the magnet and knowing to call 911; and the long-term impact is faster emergency response and better outcomes for stroke patients. The plan is feasible because partners provide space, expertise and materials.'},sources:[RULES,CTB,CDC_COMM]};

export const CA4={title:'Building community partnerships',hook:'A team of four students can reach a few hundred people. A team of four working with a hospital, a library, a radio station and a youth league can reach thousands—and earn credibility the students could not achieve alone. Judges score cooperative work with local community partners, and the strongest score requires four or more examples of partner impact.',objectives:['Identify potential community partners for a health campaign.','Approach partners professionally and define roles.','Maintain productive partnerships throughout the campaign.','Document partnership impact for the portfolio and presentation.'],sections:[
['Who can be a partner?',[
'Partners are organizations or individuals that share your goal or can help you reach your audience. Examples: **hospitals and clinics**, **local health departments**, **pharmacies**, **libraries**, **schools and school nurses**, **senior centers**, **youth sports leagues**, **faith communities**, **businesses**, **local media** (newspapers, radio, TV), **nonprofits** (American Heart Association chapters, food banks, environmental groups) and **government offices** (parks departments, emergency management).',
'Choose partners who can provide **expertise** (a dietitian reviewing materials), **access** (a senior center hosting workshops), **resources** (donated supplies) or **reach** (a radio station interview). One partner may offer several of these.',
'Start with organizations you already know: your school, your advisor’s contacts, family connections and local organizations that work on your topic.',
"Think about partners at different levels: a school club can spread the message to peers, a local business can donate supplies, a government office can create lasting change and a media outlet can multiply your reach. A mix of partner types strengthens both your campaign and your evidence.",
match('Partner and contribution',[['Hospital dietitian','Expertise reviewing nutrition messages'],['Senior center','Access to older adults'],['Local radio station','Reach through an interview'],['Pharmacy','Medication take-back site'],['Library','Event space and promotion'],['Youth sports league','Access to athletes and parents']])]],
['Approaching partners',[
'Contact potential partners professionally by email or phone. Introduce your team, HOSA and your health science program; explain your campaign’s **purpose**, **audience** and **goal**; describe **what you are asking** (for example, hosting a workshop or reviewing materials) and **what you offer** (volunteers, outreach, a youth perspective); and propose a meeting. Copy your advisor.',
'Bring a one-page **campaign summary** to meetings. Listen to the partner’s goals and adapt—partnerships work best when both sides benefit. Follow up with a thank-you and a written summary of what you agreed.',
'Be patient and polite; busy organizations may take time to reply. Contact several potential partners so the campaign does not depend on one.',
"If an organization says no, thank them and ask whether they can suggest another contact. Many partnerships begin with a referral from someone who could not help directly.",
order('Approaching a partner',['Research the organization','Email a short, professional introduction','Explain purpose, audience and goal','Describe the request and what you offer','Propose a meeting and copy your advisor','Follow up with thanks and a written summary'])]],
['Defining roles and expectations',[
'Agree on **who does what**, **when**, and **how you will communicate**. For example: the hospital dietitian reviews flyers within one week of receiving them; the senior center reserves a room and promotes workshops in its newsletter; the team designs materials, runs workshops and sends attendance reports.',
'Some teams use a simple written **agreement** or email that lists roles, dates and contacts. Clarify approval steps—some organizations must approve use of their name or logo and any media mentions.',
'Clear expectations prevent misunderstandings and make it easier to describe partnerships in your portfolio and presentation.',
chk('Why get approval before using a partner’s name or logo?',['Organizations often need to approve how they are represented','It is never required','Logos are always free to use','To make the portfolio longer'],'Respect partners’ branding rules.')]],
['Maintaining the partnership',[
'Keep partners informed with brief updates after each activity: what happened, how many people participated and photos (with consent). Ask for feedback and invite them to events. Be reliable—meet deadlines and show up on time.',
'Recognize partners publicly (with permission) in social media posts, newsletters and press releases, and thank them privately. A strong relationship may lead to new opportunities, such as a radio station offering a second interview or a hospital inviting the team to a health fair.',
'Keep a **partner log** of contacts, meetings, agreements and contributions. It is the basis for your documentation of partnership impact.',
sort('Good partnership practice?',['Good practice','Poor practice'],[['Sending a brief update after each event',0],['Missing an agreed deadline without notice',1],['Thanking partners publicly with permission',0],['Using a logo without approval',1],['Keeping a partner log',0],['Only contacting partners when you need something',1]])]],
['Documenting partnership impact',[
'The Round Two rubric awards the most points for **strong evidence (4+ examples)** that partnerships had a **high level of impact** on the community and created positive change. Examples might include: a hospital expanding your workshop to its patient education program; a library hosting three events reaching 150 people; a radio interview reaching an estimated audience; a business donating water bottles; a city adding a recycling bin at a park after your clean-up.',
'Document each example with **dates**, **numbers**, **photos** and **partner quotes**. In the portfolio, describe the partnership within your activities and publicity pages; in the presentation, describe at least four concrete examples clearly.',
'Partner impact is strongest when it creates **lasting change**, such as a new policy, a permanent display or an ongoing program.',
"In the portfolio, mention partners within activity descriptions and publicity pages; in the presentation, describe each partner’s contribution in one clear sentence with a number or result. Judges should be able to picture what each partner did and what changed because of it.",
flip('Partnership impact examples',[['Expanded reach','Library hosted three events for 150 people'],['Media','Radio interview reached a large local audience'],['Resources','Business donated 200 water bottles'],['Expertise','Dietitian reviewed every message'],['Lasting change','City added recycling bins at the park'],['Ongoing program','Hospital adopted the workshop']])]],
['Ethics and professionalism',[
'Represent HOSA professionally in every interaction. Be honest about what your team can do, protect the privacy of people you serve, avoid promoting products or businesses beyond their role as partners and follow health guidance from qualified professionals.',
'If your topic involves sensitive issues—such as mental health, substance use or eating disorders—work closely with professionals, follow safe messaging guidelines and include resources for help.',
'Professional behavior builds trust and makes partners eager to work with your chapter again in future years.',
sort('Professional or unprofessional?',['Professional','Unprofessional'],[['Following a nurse’s guidance on medical content',0],['Promising a partner more than the team can deliver',1],['Protecting participants’ privacy',0],['Endorsing a partner’s products in campaign materials',1],['Including help resources for sensitive topics',0]])]],
['Practice scenario',[
kase('Building partnerships',{a:{text:'Your water-drinking campaign needs more reach. (Scenario invented for practice.) Which partner adds the most?',choices:[['The school nutrition department plus a local radio station and a hospital dietitian','b','Correct. Access, reach and expertise.',true],['A soda company sponsor','b','That conflicts with your message.',false]]},b:{text:'The nutrition department agrees to install a water bottle filling station counter. How do you document it?',choices:[['Record the date, before-and-after counter readings, photos and a staff quote','c','Correct.',true],['Mention it vaguely','c','Specific evidence earns points.',false]]},c:{text:'This becomes one of four strong partnership impact examples in your presentation.',end:true}})]]
],takeaways:['Partners (hospitals, health departments, pharmacies, libraries, schools, senior centers, leagues, faith groups, businesses, media, nonprofits) provide expertise, access, resources and reach.','Approach partners professionally with purpose, audience, goal, request and offer; define roles, timelines and approvals (especially names and logos); keep partners updated and thanked; maintain a partner log.','Document four or more concrete examples of partner impact with dates, numbers, photos and quotes, ideally including lasting change; act ethically and follow professional guidance on sensitive topics.'],terms:[['Community partner','An organization or person that helps carry out a campaign.'],['Partner log','A record of partner contacts, meetings and contributions.'],['Lasting change','An ongoing program, policy or resource created by a campaign.']],mcqs:[q('Which partner provides expertise for a nutrition campaign?','A hospital dietitian','A soda company','A random influencer','No one','Expertise.'),q('How many examples of partnership impact earn the top Round Two score?','Four or more','One','Two','Three','Strong evidence.'),q('What should a first email to a partner include?','Purpose, audience, goal, request and what you offer','Only “Can you help?”','A demand for money','Nothing about HOSA','Professional.'),q('Why get approval before using a partner’s logo?','Organizations often must approve their representation','It is never needed','Logos are public domain','To save time','Respect branding.'),q('A partner log records:','Contacts, meetings and contributions','Team members’ grades','Only photos','The judges’ names','Documentation.'),q('Which shows lasting change?','A city adding recycling bins after a clean-up','A single poster','A one-time tweet','A thank-you card','Ongoing impact.'),q('Which partner conflicts with a water-drinking campaign?','A soda company sponsor','A hospital','A library','A school nutrition department','Mixed message.'),q('What should you send partners after each activity?','A brief update with results','Nothing','A bill','A complaint','Keep them informed.')],frq:{prompt:'Describe how your team would find, approach and work with community partners, and how you would document four examples of partnership impact.',rubric:[['Finding partners',['hospital','library','health department','school','media','expertise','access','reach']],['Approach',['professional','purpose','goal','request','offer','advisor','meeting']],['Working together',['roles','dates','approval','logo','updates','thank','log']],['Documentation',['four','dates','numbers','photos','quotes','lasting change']]],model:'For a stroke awareness campaign for older adults, we would list potential partners who offer expertise, access, resources and reach: a local hospital’s stroke coordinator, two senior centers, the public library, a community pharmacy and a local radio station. We would email each one professionally, copying our advisor, introducing HOSA and our team, explaining that our goal is to help older adults recognize stroke warning signs and call 911, describing what we are asking—such as hosting a workshop or reviewing materials—and what we offer, including volunteers and bilingual materials, and proposing a short meeting. At each meeting we would agree on roles and dates: the stroke coordinator reviews our flyers within a week, the senior centers reserve rooms and promote workshops and the library hosts a session and posts our display. We would ask permission before using any organization’s name or logo and keep a partner log of every contact and contribution. After each event, we would send partners a brief update with attendance and photos taken with consent, and thank them publicly and privately. We would document four examples of partner impact with dates, numbers, photos and quotes: the hospital coordinator reviewing every message and co-teaching two workshops; the senior centers hosting four workshops for 120 members; the radio station airing an interview to its estimated local audience; and the pharmacy agreeing to keep our stroke-sign display at its counter permanently, a lasting change.'},sources:[RULES,CTB]};

export const CA5={title:'Designing activities and original items',hook:'A table with a stack of pamphlets attracts few people. A booth with a blood pressure demonstration, a myth-or-fact spinning wheel and a QR code to a student-made video draws a crowd. Judges score original, high-quality activities and four or more original items. This lesson shows how to design campaign activities that inform, engage and inspire action.',objectives:['Apply health communication and behavior change principles.','Design engaging events, presentations and digital content.','Create four or more high-quality original items.','Make materials accurate, accessible and appropriate for the audience.'],sections:[
['Principles of effective health communication',[
'Effective messages are **accurate**, **clear**, **relevant**, **actionable** and **consistent**. Use **plain language**, focus on a few key points and tell people exactly what to do. Positive, empowering messages usually work better than fear alone. Repeat your core message across activities so it sticks.',
'Know your audience’s **health literacy** and preferences. Visuals, stories and demonstrations help people remember. Trusted messengers—peers for teens, clinicians for parents, community leaders for many groups—increase credibility.',
'CDC’s health communication guidance emphasizes understanding the audience, testing messages and evaluating results—the same cycle your campaign follows.',
"Keep messages consistent across every activity and item. If your core message is “Choose water,” every poster, post and presentation should repeat it in slightly different ways. Consistency helps people remember the message and recognize your campaign.",
sort('Effective or ineffective message?',['Effective','Ineffective'],[['“Swap one soda for water today.”',0],['A paragraph of medical jargon',1],['“Know the signs: face, arm, speech, time—call 911.”',0],['Scary images with no action step',1],['A peer telling their own healthy-habit story',0]])]],
['Behavior change theories',[
'Behavior change theories help you design activities that work. The **Health Belief Model** says people act when they believe they are at risk (susceptibility), the problem is serious (severity), action helps (benefits), barriers are manageable and a **cue to action** prompts them. The **Stages of Change** model describes moving from precontemplation to contemplation, preparation, action and maintenance.',
'**Social norms** approaches show that most peers already practice the healthy behavior. **Social cognitive theory** emphasizes **self-efficacy**—confidence in one’s ability to act—built through demonstration and practice.',
'Apply these: show risks and benefits clearly, reduce barriers (free supplies, convenient locations), provide cues to action (reminders, QR codes) and build skills through hands-on practice.',
match('Theory concept and campaign application',[['Perceived susceptibility','Local data showing teens are affected'],['Barriers','Free, convenient take-back location'],['Cue to action','Text reminder before take-back day'],['Self-efficacy','Hands-on CPR practice'],['Social norms','“Most students at our school choose water”'],['Stages of change','Different messages for people ready vs. not ready to act']])]],
['Engaging in-person activities',[
'In-person activities build knowledge and skills. Ideas: **health fair booths** with demonstrations and games; **workshops** at libraries, senior centers or schools; **skills trainings** such as hands-only CPR or Stop the Bleed (with qualified instructors); **community events** such as clean-ups, fun runs or cooking demonstrations; and **peer presentations** to classes or clubs.',
'Make activities interactive: quizzes with small prizes, myth-or-fact games, demonstrations (for example, showing the amount of sugar in drinks), pledges and sign-ups. Include an **easy action** at the end, such as signing up, scanning a QR code or taking home a supply.',
'Every team member should present or staff at least some activities, and you should photograph each one with a date (with permission) for the portfolio.',
"Plan activities for different parts of your audience. A workshop at a senior center, a booth at a youth game and a parent night presentation can deliver the same core message to different groups, multiplying impact while giving every team member a chance to lead.",
order('Planning a health fair booth',['Choose one core message','Design an interactive demonstration or game','Prepare original handouts with sources','Add an easy call to action','Assign team roles and practice','Count visitors and photograph the booth'])]],
['Digital and media activities',[
'Digital activities extend reach. Options include **social media series** (short videos, carousels, myth-busting posts), **PSAs** (public service announcements), **podcasts**, **webinars**, **websites** and **school announcements**. Create a consistent look and campaign hashtag.',
'Follow safety and privacy rules: use school or chapter accounts rather than personal ones, get permission for anyone pictured, cite sources and follow safe messaging guidelines for sensitive topics. Track views, shares and engagement with screenshots and dates for your portfolio.',
'Digital content also counts as **original items** and **publicity**—plan posts that do double duty.',
"Post at times your audience is online, such as after school for students or evenings for parents, and keep videos short enough to watch in under a minute. Pin your most important post so new visitors see it first.",
sort('Digital item type',['Video','Audio','Written or visual post'],[['30-second PSA',0],['Podcast episode with a nurse',1],['Myth-or-fact carousel',2],['Webinar recording',0],['Infographic on medication disposal',2],['Radio interview clip',1]])]],
['Creating original items',[
'The rubric rewards **four or more original, high-quality items**. Items can include **pamphlets and brochures**, **posters**, **infographics**, **social media posts**, **videos and PSAs**, **podcasts**, **webinars**, **presentation slides**, **games**, **pledge cards** and **websites**. “Original” means your team created them, not copied from another organization.',
'High quality means **accurate** (sourced facts), **clear** (plain language, readable design), **attractive** (consistent colors and fonts), **audience-appropriate** and **actionable**. Proofread carefully and have a partner expert review health content.',
'Include each item (or an image and link) in your portfolio with a short explanation of its purpose and how it was used.',
"Test items with a few members of your audience before printing or posting. Ask what they think the main message is and what they would do after seeing it. If their answer does not match your intent, revise the item.",
flip('Qualities of a high-quality item',[['Accurate','Facts cited from credible sources'],['Clear','Plain language and simple design'],['Attractive','Consistent visual identity'],['Audience-appropriate','Fits age, language and literacy'],['Actionable','Tells people what to do'],['Original','Created by your team']])]],
['Accessibility and inclusion',[
'Design materials so everyone can use them. Use **large, readable fonts** and **high contrast**, add **captions** to videos and **alt text** to images, and offer materials in the **languages** your community speaks. Choose accessible event locations and times that work for your audience.',
'Represent your community’s diversity respectfully in images and examples. Avoid stereotypes and stigmatizing language—especially for topics like mental health, weight or substance use.',
'Inclusive campaigns reach more people and demonstrate the equity values of public health.',
chk('Which choice makes a video more accessible?',['Adding captions','Using background music only','Speaking very fast','Using tiny on-screen text'],'Captions help viewers who are deaf or watching without sound.')]],
['Practice scenario',[
kase('Improving a booth',{a:{text:'Your booth has only pamphlets, and few people stop. (Scenario invented for practice.) What improves it most?',choices:[['Add an interactive sugar-in-drinks demonstration, a myth-or-fact game and a pledge sign-up','b','Correct.',true],['Add more pamphlets','b','Interaction draws people in.',false]]},b:{text:'How do you turn the booth into portfolio evidence?',choices:[['Count visitors and pledges, take dated photos with permission and include original game cards and pledge cards as items','c','Correct.',true],['Just remember it went well','c','Document everything.',false]]},c:{text:'The booth adds two original items and strong impact evidence to your portfolio.',end:true}})]]
],takeaways:['Effective health messages are accurate, clear, relevant, actionable and consistent, use plain language and trusted messengers and favor empowerment over fear alone.','Apply the Health Belief Model (susceptibility, severity, benefits, barriers, cues to action), stages of change, social norms and self-efficacy; design interactive in-person activities with an easy action and digital activities on chapter accounts.','Create four or more original, accurate, clear, attractive, audience-appropriate and actionable items; make materials accessible (large fonts, captions, alt text, languages) and inclusive; document everything with dates and numbers.'],terms:[['Health Belief Model','A theory that people act when they see risk, severity, benefits, manageable barriers and a cue to action.'],['Self-efficacy','Confidence in one’s ability to take an action.'],['Original item','Campaign material created by the team, such as a brochure or video.']],mcqs:[q('How many original items earn the top score?','Four or more','One','Two','Ten','High quality.'),q('Which is a cue to action?','A text reminder before take-back day','A long lecture','A barrier','A statistic alone','Prompts action.'),q('Self-efficacy is:','Confidence in one’s ability to act','Fear of illness','A type of poster','A partner','Built by practice.'),q('Which activity builds skills?','Hands-on CPR practice','A billboard','A tweet','A newspaper ad','Practice.'),q('Which makes an item original?','Your team created it','It was copied from a website','It has a logo','It is long','Team-made.'),q('Which improves accessibility?','Captions on videos','Tiny fonts','Low contrast','Jargon','Inclusive design.'),q('Which message is most effective?','“Swap one soda for water today.”','A page of jargon','A scary image with no action','A vague slogan','Clear and actionable.'),q('Why use chapter accounts for social media?','Privacy and professionalism','They get fewer views','Personal accounts are required','No reason','Safety.')],frq:{prompt:'Design two activities and four original items for an invented Community Awareness campaign, explaining how they apply health communication and behavior change principles.',rubric:[['Activities',['booth','workshop','demonstration','interactive','social media','psa']],['Original items',['four','pamphlet','video','infographic','pledge','podcast','original']],['Principles',['health belief','cue to action','self-efficacy','social norms','barriers','plain language']],['Quality and access',['accurate','sources','captions','languages','actionable','documented']]],model:'Our invented campaign aims to increase safe medication disposal among families in our town. Activity 1 is a series of “Clean Out Your Cabinet” booths at the library and two school open houses: visitors play a myth-or-fact game about medication storage, see a demonstration of how quickly a child can open a pill bottle, receive a free disposal bag donated by our pharmacy partner and sign a pledge to drop off unused medications on take-back day. Activity 2 is a social media series on our chapter account with short videos and infographics, plus a text-reminder sign-up before take-back day. These activities apply the Health Belief Model: local poisoning data show families’ susceptibility, the demonstration shows severity, free bags and a nearby kiosk reduce barriers and text reminders serve as cues to action. The pledge and seeing neighbors participate use social norms, and practicing the steps builds self-efficacy. Our four original items are a bilingual tri-fold brochure on safe storage and disposal, a 30-second PSA video with captions, an infographic showing where local take-back kiosks are and myth-or-fact game cards. Every item uses plain language, cites credible sources such as FDA and DEA guidance, follows our consistent color scheme, includes a clear action and was reviewed by our pharmacist partner. We will document each activity with dated photos, visitor counts, pledges signed, video views and take-back totals.'},sources:[RULES,CDC_COMM,CTB]};
